settings.custom_css:
/* ==========================================================================
   Dra. Célia Alcântara · Reumatologia
   CSS global do site (carregado pelo template de Cabeçalho do Elementor).
   Todas as classes começam com "dca-" para não colidir com tema/plugins.
   ========================================================================== */

:root {
  --dca-bg: #fdfdfd;
  --dca-linen: #f7f4ef;
  --dca-sand: #efe8dc;
  --dca-navy: #1f3363;
  --dca-navy-deep: #16264a;
  --dca-navy-soft: #2a4379;
  --dca-teal: #3aa9c8;
  --dca-teal-ink: #1d7c97;
  --dca-teal-em: #2a93b1;
  --dca-teal-hover: #5ec0db;
  --dca-teal-light: #7fcde3;
  --dca-gold: #c29f5f;
  --dca-gold-deep: #a4813f;
  --dca-gold-ink: #8c6b31;
  --dca-gold-light: #dcc293;
  --dca-ink: #1f2536;
  --dca-text: #3a4053;
  --dca-muted: #596075;
  --dca-line: #e7e1d5;
  --dca-on-navy: #eef1f7;
  --dca-on-navy-muted: #b8c2d9;

  --dca-serif: "Playfair Display", Georgia, "Times New Roman", serif;
  --dca-sans: "Poppins", system-ui, -apple-system, "Segoe UI", sans-serif;
  --dca-script: "Pinyon Script", "Playfair Display", cursive;

  --dca-ease: cubic-bezier(.23, 1, .32, 1);
  --dca-ease-io: cubic-bezier(.77, 0, .175, 1);
  --dca-radius: 22px;
  --dca-shadow: 0 30px 60px -36px rgba(31, 51, 99, .35);
}

/* ---------- Base ---------- */
html { scroll-behavior: smooth; scroll-padding-top: 110px; }
body {
  background: var(--dca-bg);
  color: var(--dca-text);
  font-family: var(--dca-sans);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
::selection { background: #cdebf3; color: var(--dca-navy-deep); }
:focus-visible { outline: 2px solid var(--dca-teal); outline-offset: 3px; border-radius: 4px; }
html { scrollbar-color: var(--dca-teal) var(--dca-bg); }
::-webkit-scrollbar { width: 10px; }
::-webkit-scrollbar-track { background: var(--dca-bg); }
::-webkit-scrollbar-thumb { background: var(--dca-sand); border-radius: 10px; border: 2px solid var(--dca-bg); }
::-webkit-scrollbar-thumb:hover { background: var(--dca-teal); }

.elementor .dca-runtime { display: none !important; }

.dca-sr {
  position: absolute !important; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0;
}
.dca-skip {
  position: fixed; left: 16px; top: -60px; z-index: 10000; padding: 12px 18px;
  background: var(--dca-navy); color: #fff !important; border-radius: 999px; font: 500 .875rem var(--dca-sans);
  transition: top .25s var(--dca-ease);
}
.dca-skip:focus { top: 16px; }

/* ---------- Tipografia ---------- */
.elementor .dca-display .elementor-heading-title,
.elementor .dca-h2 .elementor-heading-title,
.elementor .dca-h3 .elementor-heading-title,
.elementor .dca-h1-post .elementor-heading-title {
  font-family: var(--dca-serif);
  color: var(--dca-navy);
  font-weight: 400;
  text-wrap: balance;
}
.elementor .dca-display .elementor-heading-title {
  font-size: clamp(2.6rem, 1.5rem + 4vw, 4.9rem);
  line-height: 1.04;
  letter-spacing: -.025em;
}
.elementor .dca-display--md .elementor-heading-title { font-size: clamp(2.5rem, 1.6rem + 3.2vw, 4.25rem); }
.elementor .dca-h2 .elementor-heading-title {
  font-size: clamp(2rem, 1.35rem + 2.2vw, 3.1rem);
  line-height: 1.1;
  letter-spacing: -.018em;
}
.elementor .dca-h2--sm .elementor-heading-title { font-size: clamp(1.7rem, 1.3rem + 1.4vw, 2.35rem); }
.elementor .dca-h3 .elementor-heading-title {
  font-size: clamp(1.3rem, 1.1rem + .6vw, 1.6rem);
  line-height: 1.25;
  font-weight: 500;
}
.elementor .dca-h1-post .elementor-heading-title {
  font-size: clamp(2.2rem, 1.4rem + 2.8vw, 3.6rem);
  line-height: 1.1;
  letter-spacing: -.02em;
}
.elementor .elementor-heading-title em,
.dca-serif-em em {
  font-style: italic;
  color: var(--dca-teal-em);
  font-weight: 400;
}
.dca-h1-tail {
  display: block;
  margin-top: .9rem;
  font-family: var(--dca-sans);
  font-size: clamp(.95rem, .9rem + .25vw, 1.0625rem);
  font-weight: 400;
  letter-spacing: .01em;
  line-height: 1.5;
  color: var(--dca-muted);
}

.elementor .dca-lead,
.elementor .dca-prose,
.elementor .dca-small {
  font-family: var(--dca-sans);
  color: var(--dca-text);
}
.elementor .dca-lead {
  font-size: clamp(1.05rem, 1rem + .3vw, 1.2rem);
  font-weight: 300;
  line-height: 1.75;
  color: var(--dca-muted);
  max-width: 46ch;
}
.elementor .dca-lead p,
.elementor .dca-prose p { margin: 0 0 1.1em; }
.elementor .dca-lead p:last-child,
.elementor .dca-prose p:last-child,
.elementor .dca-prose ul:last-child { margin-bottom: 0; }
.elementor .dca-prose {
  font-size: 1rem;
  line-height: 1.85;
  max-width: 68ch;
}
.elementor .dca-prose strong { font-weight: 500; color: var(--dca-navy); }
.elementor .dca-prose a,
.dca-inline-link {
  color: var(--dca-teal-ink);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: .22em;
  transition: color .2s ease, text-decoration-color .2s ease;
}
.elementor .dca-prose a:hover { color: var(--dca-navy); text-decoration-color: var(--dca-teal); }
.elementor .dca-prose ul,
.dca-list {
  list-style: none;
  margin: 0 0 1.3em;
  padding: 0;
}
.elementor .dca-prose ul li,
.dca-list li {
  position: relative;
  padding-left: 1.7em;
  margin: 0 0 .75em;
}
.elementor .dca-prose ul li::before,
.dca-list li::before {
  content: "";
  position: absolute;
  left: 0;
  top: .9em;
  width: .95em;
  height: 1.5px;
  background: var(--dca-teal);
}
.elementor .dca-small { font-size: .8125rem; line-height: 1.6; color: var(--dca-muted); letter-spacing: .01em; }
.elementor .dca-measure { max-width: 60ch; }
.elementor .dca-center,
.elementor .dca-center .elementor-heading-title { text-align: center; margin-inline: auto; }

/* Texto sobre o azul-marinho */
.dca-dark { color: var(--dca-on-navy); }
.elementor .dca-dark .elementor-heading-title { color: #fff; }
.elementor .dca-dark .elementor-heading-title em { color: var(--dca-teal); }
.elementor .dca-dark .dca-lead,
.elementor .dca-dark .dca-small { color: var(--dca-on-navy-muted); }
.elementor .dca-dark .dca-prose { color: var(--dca-on-navy); }
.elementor .dca-dark .dca-prose strong { color: #fff; }
.elementor .dca-dark .dca-prose ul li::before { background: var(--dca-teal); }

/* ---------- Botões ---------- */
.elementor .dca-btn .elementor-button {
  font-family: var(--dca-sans);
  font-weight: 500;
  font-size: .9375rem;
  letter-spacing: .01em;
  line-height: 1;
  padding: 1.1em 1.9em;
  border-radius: 999px;
  background-color: var(--dca-teal);
  color: var(--dca-navy-deep);
  fill: var(--dca-navy-deep);
  border: 0;
  box-shadow: 0 14px 28px -16px rgba(22, 38, 74, .4);
  transition: background-color .3s ease, box-shadow .3s ease, transform .16s var(--dca-ease), color .3s ease;
}
.elementor .dca-btn .elementor-button-content-wrapper { gap: .65em; align-items: center; }
.elementor .dca-btn .elementor-button-icon { font-size: 1.15em; margin: 0; }
.elementor .dca-btn .elementor-button-icon svg { width: 1.1em; height: 1.1em; fill: currentColor; }
.elementor .dca-btn .elementor-button:active { transform: scale(.97); }
.elementor .dca-btn--gold .elementor-button { box-shadow: 0 14px 28px -18px rgba(0, 0, 0, .6); }
.elementor .dca-btn--ghost .elementor-button { background-color: transparent; color: var(--dca-navy); fill: var(--dca-navy); box-shadow: inset 0 0 0 1px rgba(31, 51, 99, .28); }
.elementor .dca-btn--ghost-light .elementor-button { background-color: transparent; color: #fff; box-shadow: inset 0 0 0 1px rgba(255, 255, 255, .35); }
@media (hover: hover) and (pointer: fine) {
  .elementor .dca-btn .elementor-button:hover { background-color: var(--dca-teal-hover); color: var(--dca-navy-deep); box-shadow: 0 20px 34px -18px rgba(22, 38, 74, .45); }
  .elementor .dca-btn--ghost .elementor-button:hover { background-color: transparent; color: var(--dca-navy); box-shadow: inset 0 0 0 1.5px var(--dca-teal); }
  .elementor .dca-btn--ghost-light .elementor-button:hover { background-color: rgba(255, 255, 255, .06); box-shadow: inset 0 0 0 1px #fff; }
}

/* Link de texto com sublinhado que recolhe */
.dca-link {
  display: inline-flex; align-items: center; gap: .55em;
  font: 500 .9375rem/1.4 var(--dca-sans);
  color: var(--dca-navy) !important;
  text-decoration: none !important;
  padding-bottom: 3px;
  background: linear-gradient(var(--dca-teal), var(--dca-teal)) 0 100% / 100% 1.5px no-repeat;
  transition: background-size .45s var(--dca-ease);
}
.dca-link .dca-i { width: 1em; height: 1em; color: var(--dca-teal-ink); transition: transform .35s var(--dca-ease); }
@media (hover: hover) and (pointer: fine) {
  .dca-link:hover { background-size: 0 1.5px; background-position: 100% 100%; }
  .dca-link:hover .dca-i { transform: translateX(4px); }
}
.dca-dark .dca-link { color: #fff !important; }

/* ---------- Assinatura visual: a "articulação" (linha + nó) ---------- */
.dca-joint {
  display: flex; align-items: center; gap: 10px;
  width: min(240px, 70%);
  color: var(--dca-teal);
}
.dca-joint--center { margin-inline: auto; width: 240px; max-width: 70vw; }
.elementor .dca-joint-w { width: 100%; }
.dca-joint--short { width: 120px; }
.dca-joint__line { flex: 1; height: 1px; background: currentColor; transform-origin: right center; }
.dca-joint__line + .dca-joint__node + .dca-joint__line { transform-origin: left center; }
.dca-joint__node {
  width: 11px; height: 11px; flex: none; border-radius: 50%;
  border: 1px solid var(--dca-gold);
  background: radial-gradient(circle, var(--dca-gold) 0 2px, transparent 2.5px);
}
.dca-js .dca-joint .dca-joint__line { transform: scaleX(0); transition: transform 1.2s var(--dca-ease-io) .15s; }
.dca-js .dca-joint .dca-joint__node { transform: scale(.3); opacity: 0; transition: transform .7s var(--dca-ease), opacity .5s ease; }
.dca-js .dca-joint.is-in .dca-joint__line { transform: scaleX(1); }
.dca-js .dca-joint.is-in .dca-joint__node { transform: scale(1); opacity: 1; }

/* ---------- Movimento: revelação ao rolar ---------- */
.dca-js .dca-reveal {
  opacity: 0;
  transform: translate3d(0, 24px, 0);
  filter: blur(6px);
  transition:
    opacity .9s var(--dca-ease) var(--d, 0ms),
    transform 1.1s var(--dca-ease) var(--d, 0ms),
    filter .9s var(--dca-ease) var(--d, 0ms);
}
.dca-js .dca-reveal.is-in { opacity: 1; transform: none; filter: none; }

/* Imagens: cortina que sobe + leve zoom de assentamento */
.dca-js .dca-img-reveal img {
  clip-path: inset(100% 0 0 0);
  transform: scale(1.08);
  transition: clip-path 1.4s var(--dca-ease-io), transform 1.8s var(--dca-ease);
}
.dca-js .dca-img-reveal.is-in img { clip-path: inset(0 0 0 0); transform: none; }

/* Título do topo: entrada orquestrada ao carregar */
.dca-js .dca-load { opacity: 0; transform: translate3d(0, 28px, 0); filter: blur(8px); }
.dca-js.dca-ready .dca-load {
  opacity: 1; transform: none; filter: none;
  transition: opacity 1s var(--dca-ease) var(--d, 0ms), transform 1.2s var(--dca-ease) var(--d, 0ms), filter 1s var(--dca-ease) var(--d, 0ms);
}

.elementor-editor-active .dca-reveal,
.elementor-editor-active .dca-load,
.elementor-editor-active .dca-img-reveal img,
.elementor-editor-active .dca-joint * { opacity: 1 !important; transform: none !important; filter: none !important; clip-path: none !important; }

/* ---------- Imagens ---------- */
.elementor .dca-arch { position: relative; isolation: isolate; }
.elementor .dca-arch img {
  display: block; width: 100%; height: auto;
  aspect-ratio: 4 / 5; object-fit: cover;
  border-radius: 50% 50% 28px 28px / 40% 40% 28px 28px;
  background: var(--dca-sand);
}
.elementor .dca-arch::after {
  content: ""; position: absolute; z-index: -1;
  inset: 22px -22px -22px 22px;
  border: 1px solid var(--dca-gold);
  border-radius: 50% 50% 32px 32px / 40% 40% 32px 32px;
  pointer-events: none;
}
.dca-js .elementor .dca-arch::after { clip-path: inset(100% 0 0 0); transition: clip-path 1.8s var(--dca-ease-io) .5s; }
.dca-js .elementor .dca-arch.is-in::after { clip-path: inset(0 0 0 0); }
.elementor .dca-dark .dca-arch::after { border-color: var(--dca-gold-light); }

.elementor .dca-rounded img {
  display: block; width: 100%; height: auto;
  aspect-ratio: var(--ratio, 5 / 4); object-fit: cover;
  border-radius: 28px; background: var(--dca-sand);
}
.elementor .dca-rounded--tall { --ratio: 4 / 5; }
.elementor .dca-rounded--wide { --ratio: 16 / 9; }
.elementor .dca-circle img {
  display: block; width: 100%; max-width: 420px; height: auto; margin-inline: auto;
  aspect-ratio: 1; object-fit: cover; border-radius: 50%;
  background: var(--dca-sand);
}
.elementor .dca-circle { position: relative; isolation: isolate; }
.elementor .dca-circle::before {
  content: ""; position: absolute; z-index: -1; left: 50%; top: 50%;
  width: min(116%, 488px); aspect-ratio: 1; translate: -50% -50%;
  border-radius: 50%; border: 1px solid var(--dca-gold);
}
.dca-js .elementor .dca-circle::before { opacity: 0; scale: .9; transition: opacity 1s ease .3s, scale 1.6s var(--dca-ease) .3s; }
.dca-js .elementor .dca-circle.is-in::before { opacity: 1; scale: 1; }
.dca-caption { font: 400 .8125rem/1.5 var(--dca-sans); color: var(--dca-muted); margin-top: .75rem; }

/* ---------- Topo (hero) ---------- */
.elementor .dca-clip,
.elementor .dca-sec { overflow-x: clip; }
.elementor .dca-sticky { position: sticky; top: 120px; align-self: flex-start; }
@media (max-width: 1024px) { .elementor .dca-sticky { position: relative; top: 0; } }
@media (max-width: 767px) { .elementor .dca-arch::after { inset: 12px -10px -12px 10px; } .dca-band-facts { grid-template-columns: 1fr; } .dca-credential .dca-dot { display: none; } }
.elementor .dca-hero-media { position: relative; }
.elementor .dca-hero-media::before {
  content: ""; position: absolute; z-index: 0;
  right: -12vw; top: 12%; bottom: -8%; width: 78%;
  background: var(--dca-linen);
  border-radius: 40px 0 0 40px;
}
.elementor .dca-hero-media :where(.elementor-widget) { position: relative; z-index: 1; }
.dca-credential {
  display: flex; flex-wrap: wrap; align-items: center; gap: 10px 18px;
  font: 400 .8125rem/1.5 var(--dca-sans); color: var(--dca-muted); letter-spacing: .02em;
}
.dca-credential b { font-weight: 500; color: var(--dca-navy); }
.dca-credential .dca-dot { width: 4px; height: 4px; border-radius: 50%; background: var(--dca-teal); }

.dca-float-card {
  display: flex; align-items: center; gap: 14px;
  width: max-content; max-width: 290px;
  padding: 14px 18px 14px 14px;
  background: #fff;
  border: 1px solid var(--dca-line);
  border-radius: 18px;
  box-shadow: var(--dca-shadow);
  font: 400 .8125rem/1.45 var(--dca-sans); color: var(--dca-muted);
}
.dca-float-card strong { display: block; font: 500 .875rem/1.35 var(--dca-sans); color: var(--dca-navy); }
.dca-float-card__icon {
  width: 42px; height: 42px; flex: none; display: grid; place-items: center;
  border-radius: 50%; background: var(--dca-linen); color: var(--dca-teal-ink);
}
.dca-float-card__icon .dca-i { width: 20px; height: 20px; }
.elementor .dca-float { position: absolute; z-index: 3; left: -36px; bottom: 9%; width: auto; }
@media (max-width: 767px) { .elementor .dca-float { left: 12px; bottom: -22px; } }

/* Breadcrumb */
.dca-crumbs ol { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px 10px; font: 400 .8125rem/1.5 var(--dca-sans); color: var(--dca-muted); }
.dca-crumbs li { display: inline-flex; align-items: center; gap: 10px; }
.dca-crumbs li + li::before { content: ""; width: 14px; height: 1px; background: var(--dca-teal); }
.dca-crumbs a { color: var(--dca-muted); text-decoration: none; transition: color .2s ease; }
.dca-crumbs a:hover { color: var(--dca-navy); }
.dca-crumbs [aria-current] { color: var(--dca-navy); font-weight: 500; }

/* ---------- Faixa de atendimento ---------- */
.dca-band-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 18px 28px; margin: 0; padding: 0; list-style: none; }
.dca-band-facts li { display: flex; align-items: center; gap: 12px; font: 400 .9375rem/1.45 var(--dca-sans); color: var(--dca-on-navy); }
.dca-band-facts .dca-i { width: 20px; height: 20px; color: var(--dca-teal); flex: none; }
.dca-band-facts small { display: block; color: var(--dca-on-navy-muted); font-size: .8125rem; }

/* ---------- Palavras-chave em linha (o que é reumatologia) ---------- */
.dca-structures { display: flex; flex-wrap: wrap; align-items: center; gap: 6px 18px; margin: 0; padding: 0; list-style: none; }
.dca-structures li { font: italic 400 clamp(1.15rem, 1rem + .6vw, 1.45rem)/1.4 var(--dca-serif); color: var(--dca-navy); display: inline-flex; align-items: center; gap: 18px; }
.dca-structures li + li::before { content: ""; width: 5px; height: 5px; border-radius: 50%; background: var(--dca-teal); }

/* ---------- Índice de especialidades ---------- */
.dca-index { list-style: none; margin: 0; padding: 0; border-bottom: 1px solid var(--dca-line); }
.dca-index li { border-top: 1px solid var(--dca-line); position: relative; }
.dca-index a {
  position: relative;
  display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.1fr) auto; align-items: center; gap: 12px 40px;
  padding: 30px 6px;
  text-decoration: none; color: inherit;
}
.dca-index a::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: -1px; height: 1px;
  background: var(--dca-teal); transform: scaleX(0); transform-origin: left center;
  transition: transform .7s var(--dca-ease);
}
.dca-index h3 {
  margin: 0; font: 400 clamp(1.45rem, 1.15rem + 1vw, 2rem)/1.15 var(--dca-serif); color: var(--dca-navy);
  transition: transform .5s var(--dca-ease), color .3s ease;
}
.dca-index p { margin: 0; font: 400 .9375rem/1.65 var(--dca-sans); color: var(--dca-muted); }
.dca-arrow {
  width: 50px; height: 50px; border-radius: 50%; display: grid; place-items: center;
  border: 1px solid var(--dca-line); color: var(--dca-navy);
  transition: background-color .4s var(--dca-ease), border-color .4s ease, color .3s ease, transform .5s var(--dca-ease);
}
.dca-arrow .dca-i { width: 18px; height: 18px; transform: rotate(-45deg); transition: transform .5s var(--dca-ease); }
@media (hover: hover) and (pointer: fine) {
  .dca-index a:hover::after { transform: scaleX(1); }
  .dca-index a:hover h3 { transform: translateX(10px); }
  .dca-index a:hover h3 em, .dca-index a:hover h3 { color: var(--dca-navy-soft); }
  .dca-index a:hover .dca-arrow { background: var(--dca-teal); border-color: var(--dca-teal); color: var(--dca-navy-deep); }
  .dca-index a:hover .dca-arrow .dca-i { transform: rotate(0); }
}
@media (max-width: 767px) {
  .dca-index a { grid-template-columns: minmax(0, 1fr) auto; padding: 24px 2px; }
  .dca-index p { grid-column: 1 / -1; grid-row: 2; }
  .dca-arrow { width: 42px; height: 42px; grid-row: 1; grid-column: 2; }
}

/* ---------- Cartões que viram (Como vou ajudar você) ---------- */
.dca-steps { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 20px; margin: 0; padding: 0; list-style: none; }
.dca-flip { perspective: 1400px; min-height: 330px; cursor: pointer; border-radius: var(--dca-radius); }
.dca-flip:focus-visible { outline-offset: 6px; }
.dca-flip__inner {
  position: relative; height: 100%; min-height: inherit;
  transform-style: preserve-3d;
  transition: transform .9s var(--dca-ease-io);
}
.dca-flip.is-flipped .dca-flip__inner,
html:not(.dca-js) .dca-flip:focus .dca-flip__inner { transform: rotateY(180deg); }
@media (hover: hover) and (pointer: fine) { .dca-flip:hover .dca-flip__inner { transform: rotateY(180deg); } }
.dca-flip__face {
  position: absolute; inset: 0;
  display: flex; flex-direction: column;
  padding: 30px 28px;
  border-radius: var(--dca-radius);
  backface-visibility: hidden; -webkit-backface-visibility: hidden;
}
.dca-flip__front { background: #fff; border: 1px solid var(--dca-line); justify-content: space-between; }
.dca-flip__back { background: var(--dca-navy); color: var(--dca-on-navy); transform: rotateY(180deg); justify-content: center; }
.dca-flip__num { font: italic 400 3.4rem/1 var(--dca-serif); color: var(--dca-teal-em); }
.dca-flip h3 { margin: 0; font: 400 1.4rem/1.25 var(--dca-serif); color: var(--dca-navy); }
.dca-flip__back h3 { color: var(--dca-teal-light); font-size: 1.15rem; margin-bottom: .8rem; }
.dca-flip__back p { margin: 0; font: 300 .9375rem/1.7 var(--dca-sans); }
.dca-flip__hint { display: inline-flex; align-items: center; gap: 8px; margin-top: 18px; font: 400 .75rem/1 var(--dca-sans); letter-spacing: .04em; color: var(--dca-muted); }
.dca-flip__hint .dca-i { width: 14px; height: 14px; color: var(--dca-teal-ink); }
@media (max-width: 1024px) { .dca-steps { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (max-width: 560px) { .dca-steps { grid-template-columns: 1fr; } .dca-flip { min-height: 260px; } }

/* ---------- Convênio ---------- */
.elementor .dca-panel { border-radius: 32px; overflow: hidden; }
.dca-shield {
  width: 64px; height: 64px; border-radius: 50%; display: grid; place-items: center;
  background: #fff; color: var(--dca-teal-ink); border: 1px solid var(--dca-line);
}
.dca-shield .dca-i { width: 28px; height: 28px; }
.dca-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 0; margin: 0; border-top: 1px solid var(--dca-sand); }
.dca-facts div { padding: 22px 22px 4px 0; }
.dca-facts div + div { padding-left: 22px; border-left: 1px solid var(--dca-sand); }
.dca-facts dt { font: 500 .75rem/1.4 var(--dca-sans); letter-spacing: .08em; text-transform: uppercase; color: var(--dca-teal-ink); margin-bottom: 6px; }
.dca-facts dd { margin: 0; font: 400 1.125rem/1.35 var(--dca-serif); color: var(--dca-navy); }
@media (max-width: 767px) {
  .dca-facts { grid-template-columns: 1fr; }
  .dca-facts div + div { padding-left: 0; border-left: 0; border-top: 1px solid var(--dca-sand); }
}

/* ---------- Sobre ---------- */
.dca-seals { display: flex; flex-wrap: wrap; gap: 10px; margin: 0; padding: 0; list-style: none; }
.dca-seals li {
  padding: 9px 16px; border-radius: 999px;
  border: 1px solid rgba(58, 169, 200, .5);
  font: 400 .8125rem/1.35 var(--dca-sans); color: var(--dca-on-navy);
}
.dca-seals b { font-weight: 500; color: var(--dca-teal-light); }
.dca-signature { margin: 0; font: 400 clamp(2.4rem, 2rem + 1.6vw, 3.4rem)/1 var(--dca-script); color: var(--dca-gold-light); }
.elementor .dca-signature .elementor-heading-title { font: inherit; color: inherit; margin: 0; }
.dca-js .dca-signature { clip-path: inset(0 100% 0 0); transition: clip-path 2.2s var(--dca-ease-io) .2s; }
.dca-js .dca-signature.is-in { clip-path: inset(0 -5% 0 0); }
.dca-credline { font: 500 .8125rem/1.5 var(--dca-sans); letter-spacing: .08em; text-transform: uppercase; color: var(--dca-teal-light); margin: 0; }

/* Linha do tempo da formação (a "coluna" articulada) */
.dca-timeline { position: relative; list-style: none; margin: 0; padding: 0; }
.dca-timeline::before, .dca-timeline::after {
  content: ""; position: absolute; left: 50%; top: 6px; bottom: 6px; width: 1px; translate: -.5px 0;
  background: rgba(58, 169, 200, .22);
}
.dca-timeline::after { background: var(--dca-teal); transform-origin: top; transform: scaleY(var(--p, 1)); }
.dca-timeline li { position: relative; width: 50%; padding: 0 48px 34px 0; text-align: right; }
.dca-timeline li:nth-child(even) { margin-left: 50%; padding: 0 0 34px 48px; text-align: left; }
.dca-timeline li::before {
  content: ""; position: absolute; z-index: 1; top: 4px; right: -7px;
  width: 13px; height: 13px; border-radius: 50%;
  border: 1px solid var(--dca-teal); background: var(--dca-navy);
  transition: background-color .5s ease, box-shadow .5s ease;
}
.dca-timeline li:nth-child(even)::before { right: auto; left: -6px; }
.dca-timeline li.is-in::before { background: var(--dca-teal); box-shadow: 0 0 0 5px rgba(58, 169, 200, .18); }
.dca-timeline .dca-tl-tag { display: block; font: 500 .75rem/1.4 var(--dca-sans); letter-spacing: .12em; text-transform: uppercase; color: var(--dca-teal-light); margin-bottom: 4px; }
.dca-timeline h4 { margin: 0; font: 400 1.2rem/1.35 var(--dca-serif); color: #fff; }
.dca-timeline p { margin: 4px 0 0; font: 300 .875rem/1.55 var(--dca-sans); color: var(--dca-on-navy-muted); }
@media (max-width: 767px) {
  .dca-timeline::before, .dca-timeline::after { left: 6px; }
  .dca-timeline li, .dca-timeline li:nth-child(even) { width: auto; margin-left: 0; padding: 0 0 28px 36px; text-align: left; }
  .dca-timeline li::before, .dca-timeline li:nth-child(even)::before { left: 0; right: auto; }
}

/* ---------- Depoimentos e mídia (espaços reservados) ---------- */
.dca-quotes { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px; margin: 0; padding: 0; list-style: none; }
.dca-quote { margin: 0; padding: 34px 30px 30px; background: #fff; border: 1px solid var(--dca-line); border-radius: var(--dca-radius); display: flex; flex-direction: column; gap: 22px; height: 100%; }
.dca-quote .dca-i { width: 34px; height: 26px; color: var(--dca-gold); }
.dca-quote blockquote { margin: 0; font: italic 400 1.15rem/1.6 var(--dca-serif); color: var(--dca-navy); flex: 1; }
.dca-quote figcaption { font: 500 .875rem/1.4 var(--dca-sans); color: var(--dca-text); }
.dca-quote figcaption span { display: block; font-weight: 400; color: var(--dca-muted); font-size: .8125rem; }
.dca-press { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 16px; margin: 0; padding: 0; list-style: none; }
.dca-press li {
  height: 96px; display: grid; place-items: center; border-radius: 18px;
  border: 1px dashed var(--dca-sand); color: var(--dca-muted); font: 400 .8125rem/1.4 var(--dca-sans); text-align: center; padding: 10px;
}
.dca-press img { max-height: 44px; width: auto; filter: grayscale(1); opacity: .75; transition: filter .3s ease, opacity .3s ease; }
.dca-press a:hover img { filter: none; opacity: 1; }
.dca-placeholder-note { font: 400 .8125rem/1.5 var(--dca-sans); color: var(--dca-teal-ink); }
@media (max-width: 1024px) { .dca-quotes { grid-template-columns: 1fr; } .dca-press { grid-template-columns: repeat(2, minmax(0, 1fr)); } }

/* ---------- Perguntas frequentes ---------- */
.dca-faq { border-top: 1px solid var(--dca-line); }
.dca-faq details { border-bottom: 1px solid var(--dca-line); }
.dca-faq summary {
  list-style: none; cursor: pointer;
  display: flex; align-items: center; justify-content: space-between; gap: 24px;
  padding: 26px 4px;
}
.dca-faq summary::-webkit-details-marker { display: none; }
.dca-faq summary h3 { margin: 0; font: 400 clamp(1.1rem, 1rem + .4vw, 1.3rem)/1.4 var(--dca-serif); color: var(--dca-navy); }
.dca-faq__icon { position: relative; width: 36px; height: 36px; flex: none; border-radius: 50%; border: 1px solid var(--dca-line); transition: background-color .3s ease, border-color .3s ease, transform .5s var(--dca-ease); }
.dca-faq__icon::before, .dca-faq__icon::after { content: ""; position: absolute; left: 50%; top: 50%; width: 12px; height: 1px; background: var(--dca-navy); translate: -50% -50%; transition: transform .4s var(--dca-ease), background-color .3s ease; }
.dca-faq__icon::after { transform: rotate(90deg); }
.dca-faq details[open] .dca-faq__icon { background: var(--dca-teal); border-color: var(--dca-teal); transform: rotate(180deg); }
.dca-faq details[open] .dca-faq__icon::before, .dca-faq details[open] .dca-faq__icon::after { background: var(--dca-navy-deep); }
.dca-faq details[open] .dca-faq__icon::after { transform: rotate(0); }
@media (hover: hover) and (pointer: fine) { .dca-faq summary:hover .dca-faq__icon { border-color: var(--dca-teal); } }
.dca-faq__a { padding: 0 64px 28px 4px; font: 400 1rem/1.8 var(--dca-sans); color: var(--dca-text); max-width: 72ch; }
.dca-faq__a p { margin: 0; }
.dca-js .dca-faq details[open] .dca-faq__a { animation: dca-faq-in .5s var(--dca-ease); }
@keyframes dca-faq-in { from { opacity: 0; transform: translateY(-6px); } to { opacity: 1; transform: none; } }

/* ---------- Páginas de especialidade ---------- */
.dca-toc { position: sticky; top: 120px; }
.dca-toc p { margin: 0 0 14px; font: 500 .75rem/1.4 var(--dca-sans); letter-spacing: .1em; text-transform: uppercase; color: var(--dca-teal-ink); }
.dca-toc ol { list-style: none; margin: 0; padding: 0; border-left: 1px solid var(--dca-line); }
.dca-toc a {
  position: relative; display: block; padding: 8px 0 8px 18px; margin-left: -1px;
  border-left: 1px solid transparent;
  font: 400 .875rem/1.45 var(--dca-sans); color: var(--dca-muted); text-decoration: none;
  transition: color .25s ease, border-color .25s ease, transform .4s var(--dca-ease);
}
.dca-toc a:hover { color: var(--dca-navy); }
.dca-toc a.is-active { color: var(--dca-navy); border-left-color: var(--dca-teal); transform: translateX(4px); font-weight: 500; }
@media (max-width: 1024px) { .elementor .dca-toc-col { display: none; } }

.elementor .dca-article-col .elementor-widget-heading { margin-top: 28px; }
.elementor .dca-article-col .elementor-widget-heading:first-child { margin-top: 0; }

.dca-reviewed {
  display: flex; align-items: center; gap: 14px;
  padding: 18px 20px; border-radius: 18px; background: var(--dca-linen);
  font: 400 .8125rem/1.5 var(--dca-sans); color: var(--dca-muted);
}
.dca-reviewed strong { display: block; color: var(--dca-navy); font-weight: 500; font-size: .875rem; }
.dca-reviewed__mark { width: 40px; height: 40px; flex: none; border-radius: 50%; display: grid; place-items: center; background: #fff; color: var(--dca-teal-ink); border: 1px solid var(--dca-line); }
.dca-reviewed__mark .dca-i { width: 18px; height: 18px; }

.dca-related { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 18px; }
.dca-related a {
  display: flex; align-items: center; justify-content: space-between; gap: 20px;
  padding: 26px 28px; border-radius: var(--dca-radius); border: 1px solid var(--dca-line); background: #fff;
  text-decoration: none; transition: border-color .4s ease, box-shadow .5s var(--dca-ease), transform .5s var(--dca-ease);
}
.dca-related .dca-related__kicker { display: block; font: 400 .75rem/1.4 var(--dca-sans); letter-spacing: .1em; text-transform: uppercase; color: var(--dca-teal-ink); margin-bottom: 6px; }
.dca-related strong { font: 400 1.35rem/1.25 var(--dca-serif); color: var(--dca-navy); }
@media (hover: hover) and (pointer: fine) {
  .dca-related a:hover { border-color: var(--dca-teal); box-shadow: var(--dca-shadow); transform: translateY(-3px); }
  .dca-related a:hover .dca-arrow { background: var(--dca-teal); border-color: var(--dca-teal); color: var(--dca-navy-deep); }
  .dca-related a:hover .dca-arrow .dca-i { transform: rotate(0); }
}
@media (max-width: 767px) { .dca-related { grid-template-columns: 1fr; } }

.dca-disclaimer { font: italic 400 .875rem/1.6 var(--dca-sans); color: var(--dca-muted); margin: 0; }

/* ---------- Blog ---------- */
.dca-topics { display: flex; flex-wrap: wrap; gap: 10px; margin: 0; padding: 0; list-style: none; }
.dca-topics a {
  display: inline-block; padding: 10px 18px; border-radius: 999px;
  border: 1px solid var(--dca-line); background: #fff;
  font: 400 .875rem/1 var(--dca-sans); color: var(--dca-text); text-decoration: none;
  transition: background-color .3s ease, color .3s ease, border-color .3s ease, transform .16s var(--dca-ease);
}
.dca-topics a:active { transform: scale(.97); }
.dca-topics a[aria-current], .dca-topics a:hover { background: var(--dca-teal); border-color: var(--dca-teal); color: var(--dca-navy-deep); }

.elementor .dca-posts .elementor-post { background: transparent; border: 0; }
.elementor .dca-posts .elementor-post__thumbnail__link { margin-bottom: 22px !important; display: block; overflow: hidden; border-radius: 22px; }
.elementor .dca-posts .elementor-post__thumbnail { border-radius: 22px; overflow: hidden; background: var(--dca-sand); }
.elementor .dca-posts .elementor-post__thumbnail img { transition: transform 1.1s var(--dca-ease) !important; }
.elementor .dca-posts .elementor-post:hover .elementor-post__thumbnail img { transform: scale(1.05); }
.elementor .dca-posts .elementor-post__title,
.elementor .dca-posts .elementor-post__title a { font-family: var(--dca-serif) !important; font-weight: 400 !important; font-size: 1.4rem !important; line-height: 1.28 !important; color: var(--dca-navy) !important; text-decoration: none; }
.elementor .dca-posts .elementor-post__meta-data { font: 400 .75rem/1.4 var(--dca-sans) !important; letter-spacing: .08em; text-transform: uppercase; color: var(--dca-teal-ink) !important; margin: 10px 0 0 !important; }
.elementor .dca-posts .elementor-post__excerpt p { font: 400 .9375rem/1.7 var(--dca-sans) !important; color: var(--dca-muted) !important; margin-top: 10px; }
.elementor .dca-posts .elementor-post__read-more { display: inline-block; margin-top: 14px; font: 500 .875rem/1.4 var(--dca-sans) !important; color: var(--dca-navy) !important; padding-bottom: 3px; background: linear-gradient(var(--dca-teal), var(--dca-teal)) 0 100% / 100% 1.5px no-repeat; transition: background-size .45s var(--dca-ease); }
.elementor .dca-posts .elementor-post__read-more:hover { background-size: 0 1px; background-position: 100% 100%; }
.elementor .dca-posts .elementor-pagination { margin-top: 56px; font: 400 .9375rem/1 var(--dca-sans); display: flex; justify-content: center; gap: 8px; }
.elementor .dca-posts .elementor-pagination .page-numbers { display: inline-grid; place-items: center; min-width: 42px; height: 42px; padding: 0 12px; border-radius: 999px; color: var(--dca-navy); border: 1px solid var(--dca-line); margin: 0 !important; text-decoration: none; }
.elementor .dca-posts .elementor-pagination .page-numbers.current { background: var(--dca-teal); color: var(--dca-navy-deep); border-color: var(--dca-teal); }
.dca-dark .dca-posts .elementor-post__title a { color: #fff !important; }

/* Post */
.elementor .dca-post-meta .elementor-icon-list-text,
.elementor .dca-post-meta .elementor-icon-list-text a { font: 400 .8125rem/1.5 var(--dca-sans) !important; color: var(--dca-muted) !important; }
.elementor .dca-post-meta .elementor-icon-list-icon i,
.elementor .dca-post-meta .elementor-icon-list-icon svg { color: var(--dca-teal-ink) !important; fill: var(--dca-teal-ink) !important; }
.elementor .dca-article h2 { font: 400 clamp(1.55rem, 1.25rem + 1vw, 2rem)/1.2 var(--dca-serif); color: var(--dca-navy); margin: 2.2em 0 .6em; letter-spacing: -.01em; }
.elementor .dca-article h3 { font: 500 1.25rem/1.3 var(--dca-serif); color: var(--dca-navy); margin: 1.8em 0 .5em; }
.elementor .dca-article p:first-of-type,
.elementor .dca-article .dca-intro { font-size: 1.125rem; line-height: 1.8; color: var(--dca-ink); }
.elementor .dca-article blockquote { margin: 2em 0; padding: 0 0 0 1.4em; border-left: 1px solid var(--dca-teal); font: italic 400 1.25rem/1.6 var(--dca-serif); color: var(--dca-navy); }
.elementor .dca-featured img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; border-radius: 28px; display: block; background: var(--dca-sand); }
.elementor .dca-share .elementor-share-btn { border-radius: 50% !important; background: transparent !important; border: 1px solid var(--dca-line) !important; color: var(--dca-navy) !important; transition: background-color .3s ease, color .3s ease, border-color .3s ease !important; }
.elementor .dca-share .elementor-share-btn .elementor-share-btn__icon i,
.elementor .dca-share .elementor-share-btn .elementor-share-btn__icon svg { color: var(--dca-navy) !important; fill: var(--dca-navy) !important; }
.elementor .dca-share .elementor-share-btn:hover { background: var(--dca-teal) !important; border-color: var(--dca-teal) !important; }
.elementor .dca-share .elementor-share-btn:hover i,
.elementor .dca-share .elementor-share-btn:hover svg { color: var(--dca-navy-deep) !important; fill: var(--dca-navy-deep) !important; }

.dca-author { display: flex; gap: 22px; align-items: center; }
.dca-author__avatar { width: 84px; height: 84px; border-radius: 50%; flex: none; background: var(--dca-sand); overflow: hidden; display: grid; place-items: center; color: var(--dca-teal-ink); font: italic 400 1.6rem var(--dca-serif); }
.dca-author__avatar img { width: 100%; height: 100%; object-fit: cover; }
.dca-author strong { display: block; font: 400 1.25rem/1.3 var(--dca-serif); color: var(--dca-navy); }
.dca-author p { margin: 4px 0 0; font: 400 .875rem/1.6 var(--dca-sans); color: var(--dca-muted); }

/* ---------- Cabeçalho ---------- */
.elementor-location-header { position: sticky; top: var(--wp-admin--admin-bar--height, 0px); z-index: 999; }
.dca-header {
  position: relative;
  background: rgba(253, 253, 253, .97);
  border-bottom: 1px solid transparent;
  transition: transform .5s var(--dca-ease), border-color .4s ease, box-shadow .4s ease;
}
.dca-header.is-scrolled { border-bottom-color: var(--dca-line); box-shadow: 0 18px 40px -36px rgba(31, 51, 99, .45); }
.dca-header.is-hidden { transform: translateY(-100%); }
.dca-header__inner {
  max-width: 1280px; margin: 0 auto; padding: 0 28px;
  height: 80px; display: flex; align-items: center; justify-content: space-between; gap: 28px;
}
.dca-brand { display: flex; flex-direction: column; gap: 3px; text-decoration: none !important; line-height: 1; flex: none; }
.dca-brand__name { font: 400 1.45rem/1 var(--dca-serif); color: var(--dca-navy); letter-spacing: -.01em; white-space: nowrap; }
.dca-brand__name em { color: var(--dca-teal-em); }
.dca-brand__role { font: 500 .625rem/1 var(--dca-sans); letter-spacing: .26em; text-transform: uppercase; color: var(--dca-muted); }
.dca-nav__list { display: flex; align-items: center; gap: 6px; margin: 0; padding: 0; list-style: none; }
.dca-nav__item { position: relative; }
.dca-nav a, .dca-nav button {
  position: relative; display: inline-flex; align-items: center; gap: 6px;
  padding: 10px 14px; border: 0; background: none; cursor: pointer;
  font: 400 .875rem/1 var(--dca-sans); color: var(--dca-ink); text-decoration: none;
}
.dca-nav .dca-nav__link::after {
  content: ""; position: absolute; left: 14px; right: 14px; bottom: 4px; height: 1.5px; background: var(--dca-teal);
  transform: scaleX(0); transition: transform .45s var(--dca-ease);
}
.dca-nav .dca-nav__link:hover::after, .dca-nav .dca-nav__link[aria-current="page"]::after, .dca-nav .is-current .dca-nav__link::after { transform: scaleX(1); }
.dca-nav .dca-nav__link .dca-i { width: 12px; height: 12px; transition: transform .3s var(--dca-ease); }
.dca-nav .is-open .dca-nav__link .dca-i, .dca-nav .has-sub:hover .dca-nav__link .dca-i, .dca-nav .has-sub:focus-within .dca-nav__link .dca-i { transform: rotate(180deg); }
.dca-sub {
  position: absolute; top: calc(100% + 10px); left: -12px; min-width: 300px;
  margin: 0; padding: 10px; list-style: none;
  background: #fff; border: 1px solid var(--dca-line); border-radius: 18px;
  box-shadow: 0 30px 60px -30px rgba(31, 51, 99, .35);
  opacity: 0; visibility: hidden; transform: translateY(6px) scale(.98); transform-origin: top left;
  transition: opacity .2s var(--dca-ease), transform .25s var(--dca-ease), visibility 0s linear .25s;
}
.dca-sub::before { content: ""; position: absolute; left: 0; right: 0; top: -12px; height: 12px; }
.dca-nav .is-open .dca-sub, .dca-nav .has-sub:hover .dca-sub, .dca-nav .has-sub:focus-within .dca-sub { opacity: 1; visibility: visible; transform: none; transition-delay: 0s; }
.dca-sub a { display: flex; justify-content: space-between; width: 100%; padding: 12px 14px; border-radius: 12px; transition: background-color .2s ease, color .2s ease; }
.dca-sub a:hover, .dca-sub a[aria-current="page"] { background: var(--dca-linen); color: var(--dca-navy); }
.dca-sub a .dca-i { width: 14px; height: 14px; opacity: 0; transform: translateX(-4px); transition: opacity .2s ease, transform .3s var(--dca-ease); color: var(--dca-teal-ink); }
.dca-sub a:hover .dca-i { opacity: 1; transform: none; }
.dca-header__cta {
  display: inline-flex; align-items: center; gap: 10px; flex: none;
  padding: 13px 22px; border-radius: 999px;
  background: var(--dca-teal); color: var(--dca-navy-deep) !important; text-decoration: none !important;
  font: 500 .875rem/1 var(--dca-sans);
  transition: background-color .3s ease, transform .16s var(--dca-ease);
}
.dca-header__cta .dca-i { width: 17px; height: 17px; }
.dca-header__cta:hover { background: var(--dca-teal-hover); }
.dca-header__cta:active { transform: scale(.97); }

/* Menu do celular: details funciona mesmo sem JavaScript */
.dca-mmenu { display: none; }
.dca-burger { list-style: none; display: block; width: 46px; height: 46px; border-radius: 50%; border: 1px solid var(--dca-line); background: #fff; cursor: pointer; position: relative; padding: 0; }
.dca-burger::-webkit-details-marker { display: none; }
.dca-burger::marker { content: ""; }
.dca-burger .dca-burger__line { position: absolute; left: 14px; right: 14px; height: 1.5px; background: var(--dca-navy); transition: transform .45s var(--dca-ease), top .45s var(--dca-ease); }
.dca-burger .dca-burger__line:first-child { top: 18px; }
.dca-burger .dca-burger__line:last-child { top: 26px; }
.dca-mmenu[open] .dca-burger__line:first-child { top: 22px; transform: rotate(45deg); }
.dca-mmenu[open] .dca-burger__line:last-child { top: 22px; transform: rotate(-45deg); }
.dca-drawer {
  position: fixed; left: 0; right: 0; bottom: 0; top: var(--dca-drawer-top, 72px); z-index: 998;
  background: var(--dca-bg); overflow-y: auto;
  padding: 28px 28px 40px;
  animation: dca-drawer-in .4s var(--dca-ease) both;
}
@keyframes dca-drawer-in { from { opacity: 0; transform: translateY(-8px); } to { opacity: 1; transform: none; } }
.dca-drawer ul { list-style: none; margin: 0; padding: 0; }
.dca-drawer .dca-drawer__item { border-bottom: 1px solid var(--dca-line); animation: dca-drawer-in .6s var(--dca-ease) both; animation-delay: calc(var(--i, 0) * 45ms + 80ms); }
.dca-drawer .dca-drawer__link { display: block; padding: 18px 0; font: 400 1.6rem/1.2 var(--dca-serif); color: var(--dca-navy); text-decoration: none; }
.dca-drawer .dca-drawer__sub { padding: 0 0 16px; display: grid; gap: 2px; }
.dca-drawer .dca-drawer__sub a { display: block; padding: 8px 0; font: 400 .9375rem/1.4 var(--dca-sans); color: var(--dca-text); text-decoration: none; }
.dca-drawer .dca-drawer__label { display: block; padding: 18px 0 8px; font: 400 1.6rem/1.2 var(--dca-serif); color: var(--dca-navy); }
.dca-drawer__cta { margin-top: 28px; display: flex; justify-content: center; }
.dca-drawer__cta .dca-header__cta { display: inline-flex; width: 100%; justify-content: center; padding: 18px 22px; font-size: 1rem; }
body.dca-lock { overflow: hidden; }

@media (max-width: 1100px) {
  .dca-nav { display: none; }
  .dca-mmenu { display: block; }
  .dca-header__cta--top { display: none; }
}
.dca-header__actions { display: flex; align-items: center; gap: 12px; }
@media (max-width: 767px) {
  .dca-header__inner { height: 72px; padding: 0 18px; }
  .dca-brand__name { font-size: 1.25rem; }
}

/* ---------- Rodapé ---------- */
.dca-footer { color: var(--dca-on-navy); font-family: var(--dca-sans); }
.dca-footer a { color: var(--dca-on-navy); text-decoration: none; transition: color .2s ease; }
.dca-footer a:hover { color: var(--dca-teal-light); }
.dca-footer__top { display: flex; justify-content: space-between; align-items: flex-end; gap: 40px; padding-bottom: 64px; border-bottom: 1px solid rgba(255, 255, 255, .12); }
.dca-footer__statement { margin: 0; font: 400 clamp(2rem, 1.4rem + 2.4vw, 3.4rem)/1.08 var(--dca-serif); color: #fff; letter-spacing: -.02em; max-width: 16ch; }
.dca-footer__statement em { color: var(--dca-teal); }
.dca-footer__cta { display: inline-flex; align-items: center; gap: 12px; padding: 18px 28px; border-radius: 999px; background: var(--dca-teal); color: var(--dca-navy-deep) !important; font: 500 .9375rem/1 var(--dca-sans); flex: none; transition: background-color .3s ease, transform .16s var(--dca-ease); }
.dca-footer__cta:hover { background: var(--dca-teal-hover); }
.dca-footer__cta:active { transform: scale(.97); }
.dca-footer__cta .dca-i { width: 18px; height: 18px; }
.dca-footer__grid { display: grid; grid-template-columns: 1.3fr 1fr 1fr 1.4fr; gap: 48px; padding: 64px 0; }
.dca-footer__brand .dca-brand__name { color: #fff; font-size: 1.6rem; }
.dca-footer__brand .dca-brand__name em { color: var(--dca-teal); }
.dca-footer__brand .dca-brand__role { color: var(--dca-on-navy-muted); margin-top: 6px; }
.dca-footer__brand p { margin: 20px 0 0; font-size: .9375rem; line-height: 1.7; color: var(--dca-on-navy-muted); max-width: 30ch; }
.dca-footer__title { margin: 0 0 18px; font: 500 .75rem/1.4 var(--dca-sans); letter-spacing: .14em; text-transform: uppercase; color: var(--dca-teal-light); }
.dca-footer ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; font-size: .9375rem; }
.dca-footer address { font-style: normal; font-size: .9375rem; line-height: 1.7; color: var(--dca-on-navy); }
.dca-footer__contact li { display: flex; gap: 12px; align-items: flex-start; color: var(--dca-on-navy); }
.dca-footer__contact .dca-i { width: 18px; height: 18px; flex: none; margin-top: 3px; color: var(--dca-teal); }
.dca-footer__social { display: flex; gap: 10px; margin-top: 24px; }
.dca-footer__social a { width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center; border: 1px solid rgba(255, 255, 255, .2); transition: background-color .3s ease, border-color .3s ease, color .3s ease; }
.dca-footer__social a:hover { background: var(--dca-teal); border-color: var(--dca-teal); color: var(--dca-navy-deep); }
.dca-footer__social .dca-i { width: 18px; height: 18px; }
.dca-footer__bottom { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 12px 30px; padding-top: 28px; border-top: 1px solid rgba(255, 255, 255, .12); font-size: .8125rem; color: var(--dca-on-navy-muted); }
.dca-footer__bottom p { margin: 0; }
@media (max-width: 1024px) { .dca-footer__grid { grid-template-columns: 1fr 1fr; } .dca-footer__top { flex-direction: column; align-items: flex-start; } }
@media (max-width: 600px) { .dca-footer__grid { grid-template-columns: 1fr; gap: 36px; padding: 48px 0; } }

/* Botão fixo de WhatsApp */
.dca-wa {
  position: fixed; right: 22px; bottom: 22px; z-index: 990;
  display: flex; align-items: center; gap: 0;
  height: 60px; padding: 0 18px; border-radius: 999px;
  background: var(--dca-teal); color: var(--dca-navy-deep) !important; text-decoration: none !important;
  box-shadow: 0 18px 36px -14px rgba(22, 38, 74, .5);
  transition: opacity .4s var(--dca-ease), transform .5s var(--dca-ease), background-color .3s ease;
}
.dca-js .dca-wa { opacity: 0; transform: translateY(16px) scale(.96); pointer-events: none; }
.dca-js .dca-wa.is-visible { opacity: 1; transform: none; pointer-events: auto; }
.dca-wa .dca-i { width: 24px; height: 24px; flex: none; }
.dca-wa__label { max-width: 0; overflow: hidden; white-space: nowrap; font: 500 .875rem/1 var(--dca-sans); transition: max-width .5s var(--dca-ease), margin .5s var(--dca-ease); }
@media (hover: hover) and (pointer: fine) {
  .dca-wa:hover { background: var(--dca-teal-hover); }
  .dca-wa:hover .dca-wa__label { max-width: 220px; margin-left: 12px; }
}
.dca-wa:active { transform: scale(.97); }
.dca-wa::before {
  content: ""; position: absolute; inset: 0; border-radius: inherit;
  box-shadow: 0 0 0 0 rgba(58, 169, 200, .5);
  animation: dca-ring 3.2s var(--dca-ease) infinite 2s;
}
@keyframes dca-ring { 0% { box-shadow: 0 0 0 0 rgba(58, 169, 200, .5); } 70%, 100% { box-shadow: 0 0 0 16px rgba(58, 169, 200, 0); } }

/* ---------- Movimento reduzido ---------- */
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  .dca-js .dca-reveal, .dca-js .dca-load { transform: none !important; filter: none !important; transition: opacity .4s ease !important; }
  .dca-js .dca-img-reveal img { clip-path: none !important; transform: none !important; transition: none !important; }
  .dca-js .dca-joint *, .dca-js .dca-signature, .dca-js .elementor .dca-arch::after { transform: none !important; clip-path: none !important; opacity: 1 !important; transition: none !important; }
  .dca-flip__inner { transition: none; }
  .dca-wa::before { animation: none; }
  .dca-timeline::after { transform: none !important; }
}

/* Ícones da linha de data/autora e do compartilhar (tamanho fixo) */
.elementor .dca-post-meta .elementor-icon-list-icon svg { width: 14px; height: 14px; }
.elementor .dca-post-meta .elementor-icon-list-item { display: inline-flex; align-items: center; gap: 8px; }
.elementor .dca-share .elementor-share-btn svg { width: 18px; height: 18px; }

